// Arbeitsliste als HTML-Seite. Werte werden escaped, weil Mailtexte von außen kommen.
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const tag = (t) => `<span class="tag">${esc(t)}</span>`;
const reviews = $('Offene Reviews laden').all().map((i) => i.json).filter((r) => r.id);
const aufgaben = $('Offene AB-Aufgaben laden').all().map((i) => i.json).filter((r) => r.id);

// Abweichungen und Prüfgründe in Sätze übersetzen, die ein Einkäufer sofort versteht
const beschreibe = (ab) => {
  const zahl = (n) => Number(n).toLocaleString('de-DE', { maximumFractionDigits: 4 });
  const datum = (d) => (d ? (typeof d === 'string' ? d : new Date(d).toISOString()).slice(0, 10).split('-').reverse().join('.') : '–');
  const texte = (ab.abweichungen ?? []).map((a) => ({
    preis: `Preis ${zahl(a.bestellt)} → ${zahl(a.bestaetigt)} ${a.waehrung ?? ''}`,
    menge: `Menge ${zahl(a.bestellt)} → ${zahl(a.bestaetigt)}${a.grund ? ` (${a.grund})` : ''}`,
    stammdaten_pruefen: `Stammdaten prüfen${a.hinweis ? `: ${a.hinweis}` : ''}`,
    termin_unsicher: `Termin unsicher, gewünscht ${datum(a.gewuenscht)}`,
    termin_fehlt: `Kein Termin bestätigt, gewünscht ${datum(a.gewuenscht)}`,
    termin_spaeter: `Termin ${datum(a.gewuenscht)} → ${datum(a.bestaetigt)}`,
  }[a.art] ?? a.art));
  for (const g of ab.pruefgruende ?? []) {
    texte.push({
      neuer_lieferant: 'Neuer Lieferant: Kontakt aufnehmen und Termin absichern',
      liefertreue_unter_schwelle: `Liefertreue ${ab.liefertreue} % unter ${ab.schwelle} % (${ab.abc_xyz}-Artikel)`,
      blindbestaetigung_verdacht: `AB nach ${ab.bearbeitungszeit_minuten} Minuten: Blindbestätigung?`,
      absender_domain_abweichend: 'Absender-Domain passt nicht zum Lieferanten',
    }[g] ?? g);
  }
  return texte;
};

const abKarten = aufgaben.map((t) => `
  <article>
    <h2>Ticket #${esc(t.id)} · ${esc(t.lieferant)} · Bestellung ${esc(t.bestellnummer)}</h2>
    <p class="meta">${esc(t.artikel)} · zuständig: ${esc(t.zustaendig)} · ${esc(t.erstellt)}</p>
    <p>${beschreibe(t.ab_pruefung ?? {}).map(tag).join(' ')}</p>
    ${t.entwurf_text ? `<details open><summary>Antwortentwurf (${esc(t.foermlichkeit)}, ${esc(t.nachdruck)})</summary>
      ${(t.entwurf_warnungen ?? []).length ? `<p class="warnung">Bitte prüfen: ${t.entwurf_warnungen.map(esc).join(', ')}</p>` : ''}
      <pre><b>${esc(t.entwurf_betreff)}</b>\n\n${esc(t.entwurf_text)}</pre></details>` : ''}
  </article>`).join('');

const reviewKarten = reviews.map((r) => `
  <article>
    <h2>Review #${esc(r.id)} · ${esc(r.betreff)}</h2>
    <p class="meta">${esc(r.absender)} · ${esc(r.erstellt)}</p>
    <p><b>Gründe:</b> ${r.gruende.map(tag).join(' ')}</p>
    <p><b>Vorschlag des LLM:</b> ${esc(r.vorschlag ?? '–')} (Konfidenz ${esc(r.konfidenz ?? '–')}) – ${esc(r.begruendung ?? '')}</p>
    <details><summary>Mailtext</summary><pre>${esc(r.text)}</pre></details>
  </article>`).join('');

const html = `<!doctype html><html lang="de"><head><meta charset="utf-8"><title>Arbeitsliste Einkauf</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 900px; margin: 2rem auto; padding: 0 1rem; color: #1f2328; }
  article { border: 1px solid #d0d7de; border-radius: 8px; padding: 1rem 1.25rem; margin-bottom: 1rem; }
  h1 { font-size: 1.6rem; } h2 { font-size: 1.05rem; margin: 0 0 .25rem; } .meta { color: #656d76; margin: 0 0 .75rem; }
  .tag { display: inline-block; background: #fff1e5; color: #9a4b00; border-radius: 4px; padding: .1rem .4rem; margin: .1rem 0; font-size: .85rem; }
  .warnung { color: #9a4b00; }
  pre { white-space: pre-wrap; background: #f6f8fa; padding: .75rem; border-radius: 6px; font-family: inherit; }
  a.button { display: inline-block; background: #1f6feb; color: #fff; padding: .45rem .9rem; border-radius: 6px; text-decoration: none; margin-right: .5rem; }
  section { margin-bottom: 2rem; }
</style></head><body>
<h1>Arbeitsliste Einkauf</h1>
<section>
  <h2>Auftragsbestätigungen prüfen · ${aufgaben.length} offen</h2>
  <p><a class="button" href="/form/entwurf">Antwortentwurf erstellen</a></p>
  ${abKarten || '<p>Keine offenen Auftragsbestätigungen.</p>'}
</section>
<section>
  <h2>Review-Queue · ${reviews.length} offen</h2>
  <p><a class="button" href="/form/review">Review abschließen</a></p>
  ${reviewKarten || '<p>Keine offenen Reviews.</p>'}
</section>
</body></html>`;

return { json: { html } };
